25	-- gaps: 2 insert(s), 5 update(s)
26	INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-062', 'SW', 'P2', 'OPEN', 'research-batch', 'schema views over evidence_sources', 'SIX VIEWS DO NOT FILTER A SUPERSEDED SOURCE, SO A TOMBSTONE STILL READS AS LIVE THROUGH THEM. supersede-source (T1, PR #168) writes evidence_sources.superseded_by_ref_id; assess_cell.gather_sources and test_db_integrity D04 and A09 honour it, and the writers observe-term, add-extraction and add-population-match now refuse a superseded source, but the views that read evidence_sources do not. Derive the set: select name from sqlite_master where type=''view'' and sql like ''%evidence_sources%'' and sql not like ''%superseded%'' (v_convergence_sources, v_determination_provenance, v_evidence_authors, v_item_provenance, v_source_admission, v_source_reach_all on 2026-10-02). v_evidence_authors is read by the scheduled resolve_dois.py, citation_mining_completeness.py and code_currency_audit.py; v_source_admission by research_protocol_audit.py. First live case: REF-01019, superseded by REF-01031 in batch 23. Remedy is a schema change (a view migration), so it ships in a tooling-only PR; decide per view whether a tombstone should be hidden (a determination view) or shown with its pointer (an audit view). Recorded in supersede_source''s docstring as a known gap.', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23', NULL, NULL, NULL, NULL, NULL);
27	INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-063', 'DEC', 'P2', 'OPEN', 'research-batch', 'schemas/enums.py Co1SourceType; schemas/directness.py grain_for; evidence_sources.co1_source_type', 'THE LIVE CO-1 SOURCE TYPES ARE NOT THE ENUM THE WRITER CHECKS, AND THE ENGINE GRADES THEM BY FALLBACK. Derive: select ref_id, co1_source_type from evidence_sources where evidence_type=''co1'' (REF-00989 lived_experience_publication, REF-00993 dpo_position_statement, REF-01006 and REF-01009 participatory_research on 2026-10-02) against list(schemas.enums.Co1SourceType). All four values are outside the enum. grain_for(''co1'', 1, <unknown>) returns individual grain (G3), so every live Co-1 source grades individual-grain; a DPO position statement arguably carries population grain. amend-source --field evidence_type --replacement co1 --co1-source-type enforces enum membership (T1, PR #168), so retyping a source TO co1 with these values is refused until the taxonomy is settled; add-source does not check membership (zero null values today, so requiring presence is safe, membership is not). The column has no CHECK. This is a doctrine question (which community-grain classes the evidence model recognises) before it is a tooling one, so it needs an owner decision: widen the enum to what the corpus uses, or recode the four rows to the enum. The Co-1 warrant is co-production (CLAUDE.md section 6); a misgrained Co-1 source understates the community evidence.', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23', NULL, NULL, NULL, NULL, NULL);
