35	UPDATE "research_code_leads" SET "clause" = 'DB-SUA, SUA 1, 4.3.1 apartado 1 (REF-01027, extractions 98 and 99)', "status" = 'RETRIEVED', "notes" = ' || UPDATED 2026-10-02 by session_2026-10-01-research-batch-23: status ''REFERENCE-ONLY'' -> ''RETRIEVED''; clause ''ramp slope table (not independently retrieved)'' -> ''DB-SUA, SUA 1, 4.3.1 apartado 1 (REF-01027, extractions 98 and 99)''. Retrieved from the primary text as REF-01027 in batch 23. The primary''s figures are source_value_extractions 98 and 99; the secondary-page tiers in recovered_from were not read from the primary and are superseded by those rows. The clause is SUA 1 4.3.1, not ''DB-SUA 9''.', "updated_at" = '2026-10-02 02:29', "updated_by_session" = 'session_2026-10-01-research-batch-23' WHERE "lead_id" = 91;
36	UPDATE "research_code_leads" SET "clause" = 'arrêté du 8 décembre 2014, art. 2 (reproduced in the DHUP guide, REF-01030 p. 12); arrêté du 20 avril 2017 not retrieved', "notes" = ' || UPDATED 2026-10-02 by session_2026-10-01-research-batch-23: clause ''ramp slope provisions (not independently retrieved)'' -> ''arrêté du 8 décembre 2014, art. 2 (reproduced in the DHUP guide, REF-01030 p. 12); arrêté du 20 avril 2017 not retrieved''. Status stays REFERENCE-ONLY: the arrêté du 20 avril 2017 (new ERP) is still not retrieved (Légifrance blocks automated retrieval). The 2014 arrêté''s art. 2 is reproduced in REF-01030 (extractions 103 to 105); the vendor-page figures in recovered_from (5 percent recommended; 8, 10 and 12 percent exceptions) were not read from either arrêté and are not confirmed.', "updated_at" = '2026-10-02 02:29', "updated_by_session" = 'session_2026-10-01-research-batch-23' WHERE "lead_id" = 92;
37	UPDATE "research_code_leads" SET "notes" = ' || UPDATED 2026-10-02 by session_2026-10-01-research-batch-23: No longer unadmitted: admitted in batch 23 as REF-01029 (T3 grey, authored by CERMI Comunidad de Madrid, supported by the Ayuntamiento; extractions 101 and 102). Candidate 132 resolved to it. The recovered_from text above predates the admission.', "updated_at" = '2026-10-02 02:29', "updated_by_session" = 'session_2026-10-01-research-batch-23' WHERE "lead_id" = 93;
38	
39	-- parameter_declinations: 1 insert(s), 0 update(s)
40	INSERT INTO "parameter_declinations" ("term_id", "reason", "created_at", "created_by_session") VALUES ('TERM-089', 'An element, not a quantity under determination: its slope is TERM-001 (ramp gradient, parameter 3), its length TERM-091 and its landings TERM-092. A determination is keyed on a quantity; ''ramp'' has no value to determine. The term stays in the vocabulary and keeps its adjudications.', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23');
41	
42	-- term_adjudications: 14 insert(s), 0 update(s)
43	INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (64, 81, 'NAMES-EXISTING', 'TERM-001', '''ramplutning'' is the Swedish compound for ramp slope; the context states a ratio (1:12) and calls it a safety risk. It is the slope of the ramp, which is TERM-001''s definition.', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23');
44	INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (65, 82, 'NAMES-EXISTING', 'TERM-001', '''inclinação'' (Anexo 2.5.1 1) is the gradient of the ramp stated as a percentage bounded by a rise and a horizontal projection. It is the slope of the ramp, TERM-001. The rise and the projection are separate concepts (TERM-090 level difference, TERM-091 ramp run length).', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23');
45	INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (66, 83, 'NAMES-EXISTING', 'TERM-001', '''pendiente'' in SUA 1 4.3.1 is the ramp''s longitudinal gradient (a maximum percentage, with exceptions). TERM-001''s definition is the slope of an accessible ramp as a ratio or percentage.', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23');
46	INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (67, 84, 'NAMES-EXISTING', 'TERM-001', '''pendiente longitudinal'' (Orden TMA/851/2021 art. 14.2 c) is the running gradient of a ramp section, tiered by its length. It is the slope of the ramp, TERM-001; the qualifier ''longitudinal'' separates it from the cross slope, which this source states separately and which is not this term.', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23');
47	INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (68, 85, 'NAMES-EXISTING', 'TERM-001', '''Pendientes longitudinales máximas'' is the Metodología''s table heading for the maximum running gradients of ramps by length (p. 24). The ramp''s slope, TERM-001; the cross slope on the same page is a different quantity.', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23');
48	INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (69, 75, 'NAMES-EXISTING', 'TERM-089', '''경사로'' is the Korean word for ramp, the element whose gradient the clause bounds (12분의 1 이하). Element phrase, TERM-089; its gradient is TERM-001.', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23');
49	INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (70, 89, 'NAMES-EXISTING', 'TERM-089', '''경사로'' in the official law.go.kr Annex 1, same clause and same word as observation 75 (the NEPLA mirror). The ramp element, TERM-089.', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23');
50	INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (71, 76, 'NAMES-EXISTING', 'TERM-089', '''hellingbaan'' is the Dutch term for the ramp the Bbl requires where a level difference exceeds 20 mm. Element phrase, TERM-089 (the scope note already names ''hellend vlak'' as a narrower Dutch phrase).', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23');
51	INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (72, 77, 'NAMES-EXISTING', 'TERM-089', '''hellingbaan'' on the IPLO page: ''bedoeld voor personen om hoogteverschillen mee te kunnen overbruggen'', which is TERM-089''s definition (an inclined surface that bridges a level difference).', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23');
52	INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (73, 79, 'NAMES-EXISTING', 'TERM-089', '''ramp'' in BFS 2024:12 2 kap. 4 §: the element that must incline at most 1:12 to meet the requirement of 1 and 2 §§. Ramp element, TERM-089.', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23');
53	INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (74, 87, 'NAMES-EXISTING', 'TERM-089', '''hellingbanen'' (plural) in Ieder(in)''s letter: the ramp element whose requirements the letter says will be aligned with NEN 9120. Element phrase, TERM-089.', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23');
54	INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (75, 86, 'NAMES-EXISTING', 'TERM-089', '''plan incliné'' is the arrêté''s term for an inclined plane laid out where a level difference must be overcome, here bounded at a slope of 6 % or less. The French counterpart of the Dutch ''hellend vlak'' already named in TERM-089''s scope note; the ramp element.', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23');
55	INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (76, 90, 'NAMES-EXISTING', 'TERM-089', '''rampas'' in Anexo 2.5.1 of Decreto-Lei 163/2006: the ramp element, whose clause says it must have the least possible slope and meet one of the listed conditions. TERM-089; the slope is TERM-001.', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23');
56	INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (77, 88, 'DEFERRED', NULL, '''utjämning till 0-nivå'' names a levelling between walking surfaces to zero level (the text''s examples are crossings, parking spaces for people with mobility limitations, and boarding places) with a slope bound of 1:12. It may be the ramp element in its curb-ramp class (TERM-089, as ''curb ramp'' was for REF-01008) or a distinct transition element; the advisory text under 8 § does not say which, and the binding provision it advises on was not read in this pass. Deferred, not declared out of scope.', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23', '2026-10-02 02:29', 'session_2026-10-01-research-batch-23');

