95	CREATE TABLE term_adjudications (
96	    adjudication_id     INTEGER PRIMARY KEY,
97	    observation_id      INTEGER NOT NULL REFERENCES observed_terms(observation_id),
98	    -- OUTCOMES, documented HERE and not inside the CHECK. dbcore.check_values() reads
99	    -- this constraint's own value list to build the CLI's refusal, and an inline
100	    -- comment between the quoted values defeats its parser -- measured 2026-09-03,
101	    -- when a first cut of this migration carried the descriptions inside the IN(...)
102	    -- and every legitimate outcome was refused with a mangled vocabulary. The whole
103	    -- reason vocabularies come from the schema rather than a list in the code
104	    -- (CLAUDE.md §4) is defeated by punctuation the parser cannot see past.
105	    --
106	    --   NAMES-EXISTING  names a term we already hold
107	    --   NAMES-NEW       names a concept new to the vocabulary
108	    --   NOT-OURS        a real phrase, but not one of our concepts
109	    --   DEFERRED        cannot be settled on this source alone
110	    outcome             TEXT NOT NULL CHECK (outcome IN
111	                            ('NAMES-EXISTING','NAMES-NEW','NOT-OURS','DEFERRED')),
112	    term_id             TEXT REFERENCES terms(term_id),
113	    -- NOT NULL: an adjudication that does not say why cannot be contested, and the
114	    -- whole point of splitting observation from judgment is that the judgement is
115	    -- inspectable.
116	    rationale           TEXT NOT NULL,
117	    created_at          TEXT NOT NULL,
118	    created_by_session  TEXT NOT NULL,
119	    updated_at          TEXT,
120	    updated_by_session  TEXT,
121	    -- The outcome and the pointer must agree. An outcome that names a term must name
122	    -- one; an outcome that declines must not.
123	    CHECK (
124	        (outcome IN ('NAMES-EXISTING','NAMES-NEW') AND term_id IS NOT NULL)
125	     OR (outcome IN ('NOT-OURS','DEFERRED')        AND term_id IS NULL)
126	    )
127	)
